-- ════════════════════════════════════════════════════════════════════════
-- Seed del contenido del portafolio · Tarea T-05b
--
-- GENERADO AUTOMÁTICAMENTE por scripts/seed-portfolio.ts. No se edita a
-- mano: se regenera con `npm run seed:portfolio`.
--
-- Traslada el contenido de los módulos TypeScript a las tablas portfolio_*.
-- Todo es `insert ... on conflict do update`, así que es idempotente y
-- sirve también para re-sincronizar contenido que cambió en los módulos.
-- No borra ninguna fila.
-- ════════════════════════════════════════════════════════════════════════

begin;
-- portfolio_projects: 22 fila(s)
on conflict (slug) do update set
    title = excluded.title,
    description = excluded.description,
    technologies = excluded.technologies,
    repository = excluded.repository,
    demo = excluded.demo,
    category = excluded.category,
    features = excluded.features,
    highlights = excluded.highlights,
    architecture = excluded.architecture,
    position = excluded.position
;

-- portfolio_skills: 8 fila(s)
on conflict (slug) do update set
    name = excluded.name,
    percentage = excluded.percentage,
    color_hex = excluded.color_hex,
    icon = excluded.icon,
    description = excluded.description,
    category = excluded.category,
    position = excluded.position
;

-- portfolio_education_categories: 7 fila(s)
on conflict (slug) do update set
    name = excluded.name,
    position = excluded.position
;

-- portfolio_education_items: 172 fila(s)
on conflict (slug) do update set
    category_id = excluded.category_id,
    title = excluded.title,
    institution = excluded.institution,
    duration = excluded.duration,
    description = excluded.description,
    logo = excluded.logo,
    certificate = excluded.certificate,
    is_new = excluded.is_new,
    position = excluded.position
;

-- portfolio_badges: 7 fila(s)
on conflict (slug) do update set
    title = excluded.title,
    institution = excluded.institution,
    summary = excluded.summary,
    logo = excluded.logo,
    certificate = excluded.certificate,
    is_new = excluded.is_new,
    position = excluded.position
;

-- portfolio_services: 4 fila(s)
on conflict (slug) do update set
    title = excluded.title,
    description = excluded.description,
    icon = excluded.icon,
    badge = excluded.badge,
    features = excluded.features,
    gradient = excluded.gradient,
    price_min = excluded.price_min,
    price_max = excluded.price_max,
    price_currency = excluded.price_currency,
    position = excluded.position
;

-- portfolio_technologies: 42 fila(s)
on conflict (name) do update set
    icon_key = excluded.icon_key,
    color = excluded.color,
    category = excluded.category,
    position = excluded.position
;

-- portfolio_timeline: 4 fila(s)
on conflict (slug) do update set
    year = excluded.year,
    title = excluded.title,
    description = excluded.description,
    icon_key = excluded.icon_key,
    position = excluded.position
;

-- portfolio_profile: 2 fila(s)
on conflict (section) do update set
    content = excluded.content
;

commit;
