insert into public.portfolio_projects (slug, title, description, technologies, repository, demo, category, features, highlights, architecture, position)
values
  ('gestor-de-tareas-profesional-todo-app-con-patrones-avanzados-de-react', '{"es":"Gestor de Tareas Profesional - TODO App con Patrones Avanzados de React","en":"Professional Task Manager - TODO App with Advanced React Patterns"}'::jsonb, '{"es":"Aplicación moderna y completa de gestión de tareas construida con React 18 y Zustand. Incluye sistema avanzado de recordatorios con alertas de audio, dashboard estadístico, subtareas anidadas, etiquetado por colores, notas enriquecidas, timer Pomodoro, persistencia en localStorage, temas claro/oscuro, animaciones suaves y diseño responsive Mobile-First para máxima productividad.","en":"Modern and complete task management application built with React 18 and Zustand. Features advanced reminder system with audio alerts, statistical dashboard, nested subtasks, color-coded tagging, enriched notes, Pomodoro timer, localStorage persistence, light/dark themes, smooth animations and responsive Mobile-First design for maximum productivity."}'::jsonb, array['React', 'JavaScript', 'HTML', 'CSS', 'Vercel']::text[], 'https://github.com/omarhernandezrey/57-curso-react-patrones-render', 'https://57-curso-react-patrones-render.vercel.app', '{"es":"Productividad & Gestión","en":"Productivity & Management"}'::jsonb, '{"es":["CRUD Completo de Tareas: Crear, leer, actualizar y eliminar con validaciones","Estados de Tarea: Completadas, activas, atrasadas con indicadores visuales","Sistema de Prioridades: Alta, Media, Baja con códigos de color diferenciados","Fechas de Vencimiento: Establecer y seguimiento automático de tareas atrasadas","Categorías Personalizadas: Organiza tareas por contexto (Trabajo, Personal, Estudio)","Sistema Avanzado de Recordatorios: Fecha/hora específica con alertas modales","Alertas de Audio: Web Audio API generando sonido persistente cada 3 segundos","Control de Sonido: Toggle para silenciar alertas sin cerrar el modal","Dashboard de Estadísticas: Total, completadas, activas, atrasadas en tiempo real","Gráficos Estadísticos: Distribución por prioridad y progreso visual","Notas y Descripciones: Texto enriquecido para cada tarea","Sistema de Subtareas: Tareas anidadas con progreso individual","Timer Pomodoro Integrado: Sesiones de 25 min, pausa, reanuda, contador de sesiones","Etiquetas Múltiples: 8 colores diferentes para categorizar por temas","Búsqueda Inteligente: Filtro en tiempo real por título y descripción","Filtros Avanzados: Por estado, categoría, prioridad, etiqueta y fecha","Ordenamiento Dinámico: Por fecha, prioridad, alfabético, estado","Tema Oscuro/Claro: Toggle persistente con CSS variables","Diseño Responsive: Mobile-First (móvil, tablet, desktop)","Persistencia Automática: localStorage con sincronización en tiempo real","Estado Global con Zustand: Ligero, rápido y escalable","Animaciones Suaves: Framer Motion con transiciones profesionales","Diálogos de Confirmación: Modal para acciones destructivas","Rutas Protegidas: Navegación intuitiva con React Router","Accesibilidad Web: ARIA labels, semantic HTML, navegación por teclado","Modo Offline: Funciona completamente sin conexión a internet","UI Profesional: Badges, gradientes, sombras e iconografía personalizada","Performance Optimizado: Code splitting, lazy loading, memoización","Exportación de Datos: Descarga historial de tareas en JSON","Sincronización: Actualizaciones en tiempo real entre componentes"],"en":["Complete CRUD Tasks: Create, read, update and delete with validations","Task States: Completed, active, overdue with visual indicators","Priority System: High, Medium, Low with differentiated color codes","Due Dates: Set and automatic tracking of overdue tasks","Custom Categories: Organize tasks by context (Work, Personal, Study)","Advanced Reminder System: Specific date/time with modal alerts","Audio Alerts: Web Audio API generating persistent sound every 3 seconds","Sound Control: Toggle to mute alerts without closing the modal","Statistics Dashboard: Total, completed, active, overdue in real-time","Statistical Charts: Distribution by priority and visual progress","Notes and Descriptions: Rich text for each task","Subtasks System: Nested tasks with individual progress","Integrated Pomodoro Timer: 25 min sessions, pause, resume, session counter","Multiple Tags: 8 different colors for categorizing by themes","Intelligent Search: Real-time filter by title and description","Advanced Filters: By state, category, priority, tag and date","Dynamic Sorting: By date, priority, alphabetical, state","Dark/Light Theme: Persistent toggle with CSS variables","Responsive Design: Mobile-First (mobile, tablet, desktop)","Automatic Persistence: localStorage with real-time synchronization","Global State with Zustand: Lightweight, fast and scalable","Smooth Animations: Framer Motion with professional transitions","Confirmation Dialogs: Modal for destructive actions","Protected Routes: Intuitive navigation with React Router","Web Accessibility: ARIA labels, semantic HTML, keyboard navigation","Offline Mode: Works completely without internet","Professional UI: Badges, gradients, shadows and custom iconography","Optimized Performance: Code splitting, lazy loading, memoization","Data Export: Download task history in JSON","Real-time Sync: Updates across components instantly"]}'::jsonb, '{"es":["Patrones Profesionales: Componentes modulares, hooks personalizados, state management escalable","Código Educativo: Perfecto para aprender React avanzado, Zustand y mejores prácticas","Producción Ready: Optimizado, probado y listo para usar o extender","Diseño Premium: UI/UX profesional con animaciones y transiciones suaves","100% Funcional Offline: Toda la app funciona sin conexión de red"],"en":["Professional Patterns: Modular components, custom hooks, scalable state management","Educational Code: Perfect for learning advanced React, Zustand and best practices","Production Ready: Optimized, tested and ready to use or extend","Premium Design: Professional UI/UX with smooth animations and transitions","100% Offline Functional: Entire app works without internet connection"]}'::jsonb, null, 0),
  ('shopi-e-commerce-full-stack-con-autenticacion-profesional', '{"es":"Shopi - E-Commerce Full Stack con Autenticación Profesional","en":"Shopi - Full Stack E-Commerce with Professional Authentication"}'::jsonb, '{"es":"Plataforma e-commerce completa construida con React 18, Context API, React Router v6 y Tailwind CSS. Incluye sistema de autenticación JWT con validaciones profesionales, carrito de compras persistente, catálogo dinámico integrado con API pública, gestión de órdenes, panel de cuenta de usuario, y backend escalable con Express, Prisma ORM y PostgreSQL. Desplegado en Vercel con arquitectura modular, testing con Jest y componentes reutilizables.","en":"Full-stack e-commerce platform built with React 18, Context API, React Router v6, and Tailwind CSS. Features professional JWT authentication system with robust validations, persistent shopping cart, dynamic catalog integrated with public API, order management, user account dashboard, and scalable Express backend with Prisma ORM and PostgreSQL. Deployed on Vercel with modular architecture, Jest testing, and reusable components."}'::jsonb, array['React 18', 'TypeScript', 'Tailwind CSS 3', 'React Router v6', 'Context API', 'Zustand', 'Express.js', 'Prisma ORM', 'PostgreSQL', 'JWT', 'Bcryptjs', 'Zod', 'Jest', 'Vite', 'Vercel']::text[], 'https://github.com/omarhernandezrey/56-curso-react-practico-clase-21', 'https://56-curso-react-practico-clase-21.vercel.app/', '{"es":"Full Stack","en":"Full Stack"}'::jsonb, '{"es":["Sistema de autenticación JWT con credenciales seguras","Registro con validaciones (email, contraseña, nombre)","Rutas protegidas y persistencia de sesión en localStorage","Carrito de compras con agregar/eliminar productos","Catálogo dinámico de productos con búsqueda y filtrado","Integración con API pública (escuelajs.co)","Gestión de órdenes y historial de compras","Panel de cuenta con edición de perfil","Sidebar checkout con resumen de compra","Diseño responsive con mobile first","Menú adaptable para dispositivos móviles","Componentes reutilizables con Context API","Backend REST API con validaciones Zod","Testing con Jest y cobertura de casos","Documentación técnica exhaustiva"],"en":["JWT authentication system with secure credentials","Registration with validations (email, password, name)","Protected routes and session persistence in localStorage","Shopping cart with add/remove product functionality","Dynamic product catalog with search and filtering","Integration with public API (escuelajs.co)","Order management and purchase history","Account dashboard with profile editing","Sidebar checkout with purchase summary","Responsive design with mobile first approach","Adaptive menu for mobile devices","Reusable components with Context API","REST API backend with Zod validations","Testing with Jest and coverage testing","Comprehensive technical documentation"]}'::jsonb, null, null, 1),
  ('diccionario-dev-diccionario-tecnico-web-en-espanol', '{"es":"Diccionario Dev - Diccionario Técnico Web en Español","en":"Diccionario Dev - Spanish Technical Web Dictionary"}'::jsonb, '{"es":"Plataforma completa de aprendizaje para desarrollo web con más de 200 términos técnicos en español. Incluye búsqueda inteligente, preview interactivo de código, módulos de entrenamiento (quizzes, entrevistas en vivo), sistema de autenticación JWT, panel de administración, API REST documentada con OpenAPI, extensiones para navegador y VS Code. Desplegado en Vercel con PostgreSQL, Redis y arquitectura escalable.","en":"Comprehensive web development learning platform with over 200 technical terms in Spanish. Features intelligent search, interactive code preview, training modules (quizzes, live interviews), JWT authentication system, admin panel, OpenAPI-documented REST API, browser and VS Code extensions. Deployed on Vercel with PostgreSQL, Redis and scalable architecture."}'::jsonb, array['Next.js 14', 'React 18', 'TypeScript', 'Prisma ORM', 'PostgreSQL', 'Redis', 'Tailwind CSS 4', 'Zod', 'JWT', 'Vitest', 'OpenAPI', 'Vercel']::text[], 'https://github.com/omarhernandezrey/diccionario-dev', 'https://diccionario-dev-xi.vercel.app/', '{"es":"Full Stack","en":"Full Stack"}'::jsonb, '{"es":["200+ términos técnicos en español con traducciones","Preview interactivo para HTML/CSS/JavaScript/Tailwind","Sistema de autenticación JWT con cookies HttpOnly","Panel de administración completo (CRUD)","Módulos de entrenamiento: quizzes y entrevistas en vivo","API REST documentada con OpenAPI","Rate limiting con Redis","Extensiones oficiales (navegador y VS Code)","Modo offline con Service Worker","Sistema de favoritos y historial","Rutas SEO optimizadas por término","Testing con Vitest y 60%+ cobertura"],"en":["200+ technical terms in Spanish with translations","Interactive preview for HTML/CSS/JavaScript/Tailwind","JWT authentication system with HttpOnly cookies","Full admin panel (CRUD)","Training modules: quizzes and live interviews","OpenAPI-documented REST API","Rate limiting with Redis","Official extensions (browser and VS Code)","Offline mode with Service Worker","Favorites and history system","SEO-optimized routes per term","Testing with Vitest and 60%+ coverage"]}'::jsonb, null, null, 2),
  ('proyecto-react-js-aplicacion-web-lista-de-tareas', '{"es":"Proyecto React.js - Aplicación Web lista de Tareas","en":"React.js Project - Interactive Web Application"}'::jsonb, '{"es":"Proyecto práctico de React.js. Implementa componentes funcionales, hooks, enrutamiento, manejo de estado y diseño responsive. Desplegado en Vercel como demostración de una aplicación moderna y escalable.","en":"Practical React.js project. Implements functional components, hooks, routing, state management, and responsive design. Deployed on Vercel as a demonstration of a modern and scalable application."}'::jsonb, array['React', 'JavaScript', 'HTML5', 'CSS3', 'Vercel']::text[], 'https://github.com/omarhernandezrey/54-Curso-de-React.js', 'https://54-curso-de-react-js.vercel.app/', '{"es":"Frontend","en":"Frontend"}'::jsonb, null, null, null, 3),
  ('lanyard-3d-componente-interactivo-con-fisica', '{"es":"Lanyard 3D - Componente Interactivo con Física","en":"Lanyard 3D - Interactive Physics Component"}'::jsonb, '{"es":"Componente 3D ultra-realista de lanyard con física avanzada usando Three.js, React y Rapier. Simulación realista, renderizado PBR, interacción intuitiva y diseño responsive.","en":"Ultra-realistic 3D lanyard component with advanced physics using Three.js, React, and Rapier. Real-time simulation, PBR rendering, intuitive interaction, and responsive design."}'::jsonb, array['Next.js', 'React', 'TypeScript', 'Three.js', 'Rapier', '@react-three/fiber', '@react-three/drei', '@react-three/rapier', 'Tailwind CSS']::text[], 'https://github.com/omarhernandezrey/lanyard-project', 'https://lanyard-project.vercel.app/', '{"es":"3D Interactivo","en":"Interactive 3D"}'::jsonb, null, null, null, 4),
  ('product-card-proyecto-con-web-components', '{"es":"Product Card - Proyecto con Web Components","en":"Product Card - Web Components Project"}'::jsonb, '{"es":"Tarjeta de producto moderna creada con Web Components nativos usando JavaScript vanilla. Componente completamente encapsulado, reutilizable, con diseño responsive y estilos modernos.","en":"Modern product card built with native Web Components using vanilla JavaScript. Fully encapsulated, reusable component with responsive layout and modern styles."}'::jsonb, array['HTML', 'CSS', 'JavaScript', 'Web Components', 'Vercel, netlify']::text[], 'https://github.com/omarhernandezrey/32proyectoCursoDeJavaScriptWebComponents', 'https://32proyectocursodejavascriptwebcompone.netlify.app/', '{"es":"Web Components","en":"Web Components"}'::jsonb, null, null, null, 5),
  ('cinexpress-api-rest-con-javascript', '{"es":"CineXpress - API REST con JavaScript","en":"CineXpress - REST API with JavaScript"}'::jsonb, '{"es":"Explora películas en tendencia, búsquedas por categoría o nombre y detalles completos consumiendo TMDB API.","en":"Explore trending movies, search by category or name and get complete details consuming TMDB API."}'::jsonb, array['HTML', 'CSS', 'JavaScript', 'Axios', 'Vercel']::text[], 'https://github.com/omarhernandezrey/31-cursoDeApiRestConJavascriptEjemplosConApisReales', 'https://cinexpressonline.vercel.app/', '{"es":"JavaScript","en":"JavaScript"}'::jsonb, null, null, null, 6),
  ('michis-app-api-rest-con-javascript', '{"es":"Michis App - API REST con JavaScript","en":"Michis App - REST API with JavaScript"}'::jsonb, '{"es":"Guarda y sube imágenes de gatitos usando The Cat API. Proyecto de fundamentos de API REST.","en":"Save and upload cat images using The Cat API. REST API fundamentals project."}'::jsonb, array['HTML', 'CSS', 'JavaScript', 'Fetch', 'Axios']::text[], 'https://github.com/omarhernandezrey/30_cursoDeApiRestConJavascriptFundamentos', 'https://michis-app-api-rest.netlify.app/', '{"es":"JavaScript","en":"JavaScript"}'::jsonb, null, null, null, 7),
