insert into public.portfolio_services (slug, title, description, icon, badge, features, gradient, price_min, price_max, price_currency, position)
values
  ('sitios-web-profesionales', '{"es":"Sitios Web Profesionales","en":"Professional Websites"}'::jsonb, '{"es":"Tu negocio necesita una página web que venda, no solo que exista. Diseño sitios rápidos, optimizados para Google y que convierten visitantes en clientes.","en":"Your business needs a website that sells, not just exists. I design fast, Google-optimized sites that turn visitors into paying clients."}'::jsonb, '/images/services/frontend.svg', 'WEB', '{"es":["Diseño orientado a conversión","Carga en menos de 2 segundos","Optimizado para Google (SEO)","Panel para que edites tú mismo"],"en":["Conversion-focused design","Loads in under 2 seconds","Google-optimized (SEO)","Admin panel for easy editing"]}'::jsonb, 'from-blue-500 to-cyan-500', 300, 3800, 'USD', 0),
  ('aplicaciones-web-a-medida', '{"es":"Aplicaciones Web a Medida","en":"Custom Web Applications"}'::jsonb, '{"es":"¿Tu negocio necesita algo más que una página web? Construyo aplicaciones web completas con bases de datos, autenticación y funcionalidades específicas para tu operación.","en":"Need more than a website? I build complete web applications with databases, authentication, and custom features tailored to your business operations."}'::jsonb, '/images/services/backend.svg', 'APP', '{"es":["Sistemas de gestión internos","Dashboards con datos en tiempo real","Autenticación segura de usuarios","APIs para conectar con otros sistemas"],"en":["Internal management systems","Real-time data dashboards","Secure user authentication","APIs to connect with other systems"]}'::jsonb, 'from-green-500 to-emerald-500', 800, 5000, 'USD', 1),
  ('tiendas-online-e-commerce', '{"es":"Tiendas Online (E-commerce)","en":"Online Stores (E-commerce)"}'::jsonb, '{"es":"Vende tus productos online con una tienda profesional. Integro pasarelas de pago (Wompi, Stripe, PayPal), gestión de inventario y todo lo necesario para que empieces a facturar.","en":"Sell your products online with a professional store. I integrate payment gateways (Stripe, PayPal), inventory management, and everything you need to start making sales."}'::jsonb, '/images/services/design.svg', 'SHOP', '{"es":["Pagos con tarjeta, PSE y Nequi","Gestión de productos e inventario","Diseño que genera confianza para comprar","Panel administrativo intuitivo"],"en":["Credit card, PayPal and Stripe payments","Product and inventory management","Trust-building design that drives sales","Intuitive admin dashboard"]}'::jsonb, 'from-purple-500 to-pink-500', 1500, 5000, 'USD', 2),
  ('automatizacion-y-seo', '{"es":"Automatización y SEO","en":"Automation & SEO"}'::jsonb, '{"es":"Elimina tareas repetitivas y haz que Google te encuentre. Automatizo procesos de tu negocio y optimizo tu sitio para que aparezca en los primeros resultados de búsqueda.","en":"Eliminate repetitive tasks and get found on Google. I automate your business processes and optimize your site to rank on the first page of search results."}'::jsonb, '/images/services/devops.svg', 'AUTO', '{"es":["Automatización de reportes y procesos","Integración entre tus herramientas","Optimización para Google (SEO técnico)","Mejora de velocidad de carga"],"en":["Automated reports and workflows","Integration between your tools","Google optimization (technical SEO)","Page speed improvement"]}'::jsonb, 'from-orange-500 to-red-500', 300, 2500, 'USD', 3)
