insert into public.portfolio_timeline (slug, year, title, description, icon_key, position)
values
  ('fundamentos-y-formacion-tecnica', '{"es":"2020 - 2022","en":"2020 - 2022"}'::jsonb, '{"es":"Fundamentos y Formación Técnica","en":"Foundations & Technical Training"}'::jsonb, '{"es":"Inicié mi camino en desarrollo con el SENA. Cursé y aprobé el tecnólogo en Análisis y Desarrollo de Sistemas de Información (ADSI), construyendo bases sólidas en análisis, diseño y desarrollo de software. Comencé a ofrecer servicios de desarrollo web.","en":"Started my development path with SENA. Completed the ADSI (Information Systems Analysis and Development) technologist program, building solid foundations in analysis, design, and software development. Began offering web development services."}'::jsonb, 'GraduationCap', 0),
  ('expansion-a-desarrollo-web-moderno', '{"es":"2023","en":"2023"}'::jsonb, '{"es":"Expansión a Desarrollo Web Moderno","en":"Expansion into Modern Web Development"}'::jsonb, '{"es":"Ingresé al Politécnico Grancolombiano para estudiar Ingeniería de Software. Inicié formación intensiva en React.js, Vite.js, TailwindCSS y JavaScript avanzado. Comencé a construir proyectos full stack con tecnologías modernas.","en":"Enrolled at Politécnico Grancolombiano to study Software Engineering. Started intensive training in React.js, Vite.js, TailwindCSS, and advanced JavaScript. Began building full stack projects with modern technologies."}'::jsonb, 'Code2', 1),
  ('certificaciones-y-bootcamps', '{"es":"2024","en":"2024"}'::jsonb, '{"es":"Certificaciones y Bootcamps","en":"Certifications & Bootcamps"}'::jsonb, '{"es":"Completé el Bootcamp Full Stack de Talento Tech (159 horas, Ministerio TIC). Obtuve certificación ITCertificate como Full Stack Developer Certified Specialist. Desarrollé proyectos complejos como Shopi (e-commerce full stack) y Diccionario Dev (plataforma de aprendizaje con 200+ términos, PostgreSQL y Redis).","en":"Completed the Talento Tech Full Stack Bootcamp (159 hours, Ministerio TIC). Earned ITCertificate certification as a Full Stack Developer Certified Specialist. Built complex projects like Shopi (full stack e-commerce) and Diccionario Dev (a learning platform with 200+ terms, PostgreSQL, and Redis)."}'::jsonb, 'Sparkles', 2),
  ('especializacion-full-stack-y-automatizacion', '{"es":"2025 - Presente","en":"2025 - Present"}'::jsonb, '{"es":"Especialización Full Stack y Automatización","en":"Full Stack Specialization & Automation"}'::jsonb, '{"es":"Enfoque en automatización de procesos empresariales y arquitecturas escalables. Próximo a graduarme como Ingeniero de Software. Desarrollo de soluciones full stack para clientes en Colombia y remoto USA, con stack React, Next.js, Node.js y PostgreSQL.","en":"Focused on business process automation and scalable architectures. About to graduate as a Software Engineer. Building full stack solutions for clients in Colombia and remote in the US, with a React, Next.js, Node.js, and PostgreSQL stack."}'::jsonb, 'Briefcase', 3)
